sys.path.insert(0, str(Path(__file__).parent.parent))
from docx_kit import *

root = Path(__file__).parent
dyn = json.loads((root / "dynamic-results.json").read_text(encoding="utf8"))
out = root.parent / "documents"
out.mkdir(exist_ok=True)

d = new_doc("", "Лабораторная работа №1 «Тестирование требований к ПО». В документе описан вариант использования (Use Case) «Подать заявку в лист ожидания» проекта DSLKit (первоначальная версия), выполнено его тестирование методом просмотра по критериям качества требований, составлена таблица дефектов и вопросы автору, а затем сценарий проверен на работающем приложении. В конце приведена исправленная версия Use Case. Теория взята из методических указаний к работе.")


def para(text, bold=False):
    p = d.add_paragraph()
    p.add_run(text).bold = bold


